{
 "type":"mol",
 "smiles":"Cc1ccccc1Br",
 "children":[
   {
     "type":"reaction",
     "template_id":1914384,
     "children":[
        {"type":"mol","smiles":"Cc1ccccc1"},
        {"type":"mol","smiles":"Br"}
     ]
